+const EXCEL_DATA_ROWS = 1_048_575;
+const WEIGHT_TOTAL = 1_000_000n;
+// Contract: these helpers are defined for genuine dense bigint arrays. Exotic
+// array-likes and Proxies that misreport their own length or own keys are the
+// caller's responsibility and are outside this candidate.
+function assertBigint(value: unknown, label: string): asserts value is bigint {
+  if (typeof value !== 'bigint') throw new RangeError(`invalid ${label}`);
+}
+function denseBigints(values: readonly bigint[], label: string): bigint[] {
+  if (!Array.isArray(values)) throw new RangeError(`invalid ${label}`);
+  const length = values.length;
+  const snapshot: bigint[] = [];
+  for (let index = 0; index < length; index += 1) {
+    if (!Object.hasOwn(values, index)) throw new RangeError(`invalid ${label}`);
+    const value = values[index];
+    assertBigint(value, label);
+    snapshot.push(value);
+  }
+  return snapshot;
+}
+// Chunking treats row values as opaque and copies them positionally. It reads
+// only length and indexes, and never calls a method reachable from the input,
+// so an own `slice` override or a poisoned Symbol.species cannot influence it.
+// Holes are copied as undefined without consulting the prototype chain.
+export function worksheetChunks<T>(rows: readonly T[]): (T | undefined)[][] {
+  if (!Array.isArray(rows)) throw new RangeError('invalid rows');
+  const total = rows.length;
+  const chunks: (T | undefined)[][] = [];
+  for (let start = 0; start < total; start += EXCEL_DATA_ROWS) {
+    const end = Math.min(start + EXCEL_DATA_ROWS, total);
+    const chunk: (T | undefined)[] = [];
+    for (let index = start; index < end; index += 1) {
+      chunk.push(Object.hasOwn(rows, index) ? rows[index] : undefined);
+    }
+    chunks.push(chunk);
+  }
+  return chunks;
+}
+export function closingCents(
+  openingCents: bigint, inflowCents: bigint, consumptionCents: readonly bigint[]
+) {
+  assertBigint(openingCents, 'opening amount');
+  assertBigint(inflowCents, 'inflow amount');
+  const consumptions = denseBigints(consumptionCents, 'consumption values');
+  const values = [openingCents, inflowCents, ...consumptions];
+  if (values.some((value) => value < 0n)) {
+    throw new RangeError('negative minor-unit amount');
+  }
+  return openingCents + inflowCents
+    - consumptions.reduce((total, value) => total + value, 0n);
+}
+export function allocateCents(sourceCents: bigint, weights: readonly bigint[]) {
+  assertBigint(sourceCents, 'source amount');
+  const stableWeights = denseBigints(weights, 'allocation weights');
+  if (sourceCents < 0n || stableWeights.length === 0
+      || stableWeights.some((x) => x < 0n)
+      || stableWeights.reduce((total, value) => total + value, 0n) !== WEIGHT_TOTAL) {
+    throw new RangeError('invalid integer allocation');
+  }
+  const allocated = stableWeights.map((x) => sourceCents * x / WEIGHT_TOTAL);
+  const ranked = stableWeights.map((x, index) => ({
+    index, remainder: sourceCents * x % WEIGHT_TOTAL, weight: x,
+  })).filter((row) => row.weight > 0n).sort((a, b) =>
+    a.remainder === b.remainder ? a.index - b.index
+      : a.remainder > b.remainder ? -1 : 1);
+  const remainder = Number(sourceCents
+    - allocated.reduce((total, value) => total + value, 0n));
+  for (let index = 0; index < remainder; index += 1) {
+    allocated[ranked[index].index] += 1n;
+  }
+  return allocated;
+}
