+const MS_PER_UTC_DAY = 86_400_000;
+const MAX_SPAN_DAYS = 3_660;
+// Supported range: years 1000 through 9999. Two-digit years are excluded on
+// purpose - Date.UTC remaps 0..99 into the 1900s, so they are not accepted.
+const CALENDAR_DATE = /^[1-9]\d{3}-\d{2}-\d{2}$/;
+// Validation does not rely on Date.parse rejecting an out-of-range day: the
+// instant is round-tripped back to a calendar string and compared to the input,
+// which rejects anything the calendar would have rolled over instead.
+function utcMidnight(value: string): number {
+  if (typeof value !== 'string' || !CALENDAR_DATE.test(value)) {
+    throw new RangeError('invalid calendar date');
+  }
+  const instant = Date.UTC(
+    Number(value.slice(0, 4)),
+    Number(value.slice(5, 7)) - 1,
+    Number(value.slice(8, 10))
+  );
+  // Every component is bounded by the pattern above, so instant is always a
+  // valid time value and the round-trip below cannot throw on its own.
+  if (new Date(instant).toISOString().slice(0, 10) !== value) {
+    throw new RangeError('invalid calendar date');
+  }
+  return instant;
+}
+export function utcDaySpan(startDate: string, endDate: string): number {
+  const start = utcMidnight(startDate);
+  const end = utcMidnight(endDate);
+  if (end < start) throw new RangeError('reversed reporting range');
+  const span = (end - start) / MS_PER_UTC_DAY + 1;
+  if (span > MAX_SPAN_DAYS) throw new RangeError('reporting range too large');
+  return span;
+}
