+export const MAX_SAMPLE = 1_000_000;
+export function nearestRankPercentile(
+  values: readonly number[], percentile: number
+): number {
+  // The validated length is snapshotted once: re-reading it per iteration
+  // would let a container that reports a growing length escape MAX_SAMPLE.
+  const length = Array.isArray(values) ? values.length : -1;
+  if (!Number.isSafeInteger(length) || length <= 0 || length > MAX_SAMPLE) {
+    throw new RangeError('invalid latency sample');
+  }
+  if (!Number.isInteger(percentile) || percentile < 1 || percentile > 100) {
+    throw new RangeError('invalid percentile');
+  }
+  const sorted: number[] = [];
+  for (let index = 0; index < length; index += 1) {
+    // One own-property observation per element: existence and value come from
+    // the same descriptor, so a hole cannot resolve through the prototype
+    // chain and no second read can disagree with the first.
+    // Contract: defined for genuine arrays that answer truthfully about
+    // themselves. A container engineered to lie in its own property traps is
+    // the caller's responsibility and is out of scope for this candidate.
+    const slot = Object.getOwnPropertyDescriptor(values, index);
+    // An accessor descriptor carries no own `value`, so reading slot.value
+    // would resolve through Object.prototype: a polluted
+    // Object.prototype.value holding a finite number would let an accessor
+    // slot pass without its getter ever running. Require an own data value.
+    if (slot === undefined || !Object.hasOwn(slot, 'value')) {
+      throw new RangeError('invalid latency sample');
+    }
+    const value = slot.value;
+    if (typeof value !== 'number' || !Number.isFinite(value)) {
+      throw new RangeError('invalid latency sample');
+    }
+    sorted.push(value);
+  }
+  sorted.sort((left, right) => left - right);
+  // scaled is an exact integer (percentile <= 100, length <= 1e6), so the rank
+  // is ceil(scaled / 100) expressed without relying on inexact division.
+  const scaled = percentile * length;
+  const rank = (scaled - (scaled % 100)) / 100 + (scaled % 100 === 0 ? 0 : 1);
+  return sorted[rank - 1];
+}
