+assert.equal(nearestRankPercentile([5, 1, 4, 2, 3], 20), 1);
+assert.equal(nearestRankPercentile([5, 1, 4, 2, 3], 21), 2);
+assert.equal(nearestRankPercentile([10, 20, 30, 40], 95), 40);
+assert.equal(nearestRankPercentile([-2, -1, 0], 50), -1);
+const sample = [3, 1, 2];
+assert.equal(nearestRankPercentile(sample, 50), 2);
+assert.deepEqual(sample, [3, 1, 2]);
+assert.throws(() => nearestRankPercentile([], 50), RangeError);
+assert.throws(() => nearestRankPercentile([1, Number.NaN], 50), RangeError);
+assert.throws(() => nearestRankPercentile([1, Number.POSITIVE_INFINITY], 50), RangeError);
+assert.throws(() => nearestRankPercentile(Array<number>(2), 50), RangeError);
+assert.throws(() => nearestRankPercentile({ length: 1, 0: 1 } as unknown as number[], 50), RangeError);
+const inheritedSample = Array<number>(2);
+inheritedSample[0] = 1;
+const inheritedProto = Object.create(Array.prototype);
+Object.defineProperty(inheritedProto, '1', { value: 5 });
+Object.setPrototypeOf(inheritedSample, inheritedProto);
+assert.throws(() => nearestRankPercentile(inheritedSample, 50), RangeError);
+assert.throws(() => nearestRankPercentile([1, 2], 0), RangeError);
+assert.throws(() => nearestRankPercentile([1, 2], 101), RangeError);
+assert.throws(() => nearestRankPercentile([1, 2], 50.5), RangeError);
+assert.equal(nearestRankPercentile(Array.from({ length: MAX_SAMPLE }, () => 4), 50), 4);
+assert.throws(() => nearestRankPercentile(Array.from({ length: MAX_SAMPLE + 1 }, () => 4), 50), RangeError);
+let lengthReads = 0;
+const settlingLength = new Proxy([3, 1, 2], {
+  get(target, property, receiver) {
+    if (property === 'length') {
+      lengthReads += 1;
+      return lengthReads === 1 ? 3 : 1_000_000_000;
+    }
+    return Reflect.get(target, property, receiver);
+  },
+});
+assert.equal(nearestRankPercentile(settlingLength, 100), 3);
+assert.equal(lengthReads, 1);
+const accessorSample = [1, 2];
