+const BASIS_POINT_TOTAL = 10_000n;
+const MAX_BASIS_POINTS = 10_000;
+export function feeCents(amountCents: bigint, basisPoints: number): bigint {
+  if (typeof amountCents !== 'bigint' || amountCents < 0n) {
+    throw new RangeError('invalid amount');
+  }
+  if (!Number.isInteger(basisPoints) || basisPoints < 0
+      || basisPoints > MAX_BASIS_POINTS) {
+    throw new RangeError('invalid basis points');
+  }
+  const scaled = amountCents * BigInt(basisPoints);
+  const quotient = scaled / BASIS_POINT_TOTAL;
+  const remainder = scaled % BASIS_POINT_TOTAL;
+  return remainder * 2n >= BASIS_POINT_TOTAL ? quotient + 1n : quotient;
+}
